---@class UIGMControlPanel : IGUILayout
local UIGMControlPanel = class("GUIGMControlPanel", IGUILayout)

function UIGMControlPanel:onLoad()
    self.root:SetLevel(1)
    self:getChildWindow("GMControlPanel-Close-Text"):SetText("×")
    local llTabs = self:getChildWindow("GMControlPanel-Tabs")
    self.llInput = self:getChildWindow("GMControlPanel-Input-Layout", GUIType.Layout)
    self.llInput:SetVisible(false)
    self.edInput = self:getChildWindow("GMControlPanel-Input-Edit", GUIType.Edit)
    self.stHint = self:getChildWindow("GMControlPanel-Input-Hint", GUIType.StaticText)
    self.lvTabs = IGUIListView.new("GMControlPanel-Tabs-List", llTabs)
    self.lvTabs:setItemSpace(5)

    local llContent = self:getChildWindow("GMControlPanel-Content")
    local size = self.root:GetPixelSize()
    local count
    if size.x > size.y then
        count = 5
    else
        count = 2
    end
    self.gvItems = IGUIGridView.new("GMControlPanel-Items-List", llContent)
    self.gvItems:setConfig(10, 10, count)
    local itemW = (self.gvItems:getWidth() - 60) / count
    ---@type GMItemAdapter
    self.adapter = UIHelper.newEngineAdapter("GMItemAdapter")
    self.adapter:setItemSize(itemW, 40)
    self.gvItems:setAdapter(self.adapter)

    local btnClose = self:getChildWindow("GMControlPanel-Close", GUIType.Button)
    btnClose:registerEvent(GUIEvent.ButtonClick, function()
        self:hide()
    end)

    local stFilterText = self:getChildWindow("GMControlPanel-FilterText", GUIType.StaticText)
    stFilterText:SetText("过滤：")

    self.etFilterValue = self:getChildWindow("GMControlPanel-FilterValue", GUIType.Edit)
    self.etFilterValue:SetMaxLength(100)
    self.etFilterValue:registerEvent(GUIEvent.EditTextInput, function(args)
        if args.trigger == 0 then
            self:selectTab(self.tab)
        end
    end)

    self.edInput:SetMaxLength(100)
    self.edInput:registerEvent(GUIEvent.EditTextInput, function(args)
        self.stHint:SetVisible(self.edInput:GetText() == "")
        if args.trigger == 0 then
            self:inputText()
        end
    end)

    self.llInput:registerEvent(GUIEvent.Click, function()
        self:closeInput()
    end)

    self.gvItems.root:registerEvent(GUIEvent.ScrollMoveChange, function(args)
        if self.settings then
            self.settings.offset = args.offset
        end
    end)
end

---@param paramTexts string[]
---@param callBack function
function UIGMControlPanel:openInput(paramTexts, callBack)
    self.llInput:SetVisible(true)
    self.paramTexts = paramTexts
    self.inputTable = {}
    self.callBack = callBack
    LuaTimer:schedule(function()
        self:showInputBox()
    end, 50)

end

function UIGMControlPanel:showInputBox()
    self.tipText = tostring(self.paramTexts[#self.inputTable + 1])
    self.edInput:SetText("")
    self.stHint:SetText(self.tipText)
    self.stHint:SetVisible(true)
    LuaTimer:schedule(function()
        self.edInput:TouchUp({ VectorUtil.newVector2(0, 0) })
    end, 50)
end

function UIGMControlPanel:inputText()
    local text = self.edInput:GetText()
    if text == "" then
        return
    end
    table.insert(self.inputTable, text)
    if #self.inputTable < #self.paramTexts then
        self:showInputBox()
    else
        self.edInput:SetText("")
        self.stHint:SetText(self.tipText)
        self.stHint:SetVisible(true)
        if self.callBack then
            self.callBack(unpack(self.inputTable))
            self:closeInput()
        end
    end
end

function UIGMControlPanel:show()
    if not isTest and not isStaging then
        return
    end
    self.super.show(self)
end

function UIGMControlPanel:closeInput()
    self.llInput:SetVisible(false)
    self.paramTexts = {}
    self.inputTable = {}
    self.callBack = nil
end

function UIGMControlPanel:onShow()
    if self.lvTabs:getItemCount() > 0 then
        return
    end
    self:initTabs()
end

function UIGMControlPanel:isShowAnim()
    return false
end

function UIGMControlPanel:initTabs()
    for _, _tab in pairs(GMSetting:getSettings()) do
        if next(_tab.items) then
            local tab = UIHelper.newEngineGUIWindow("GUIGMTab", "GMButton.json")
            tab:onDataChanged(_tab.name)
            self.lvTabs:addItem(tab)
        end
    end
    if GMSetting:getSettings()[1] then
        self:selectTab(GMSetting:getSettings()[1].name)
    end
end

function UIGMControlPanel:selectTab(name)
    self.tab = name
    self.gvItems:clearItems()
    local settings
    for _, group in pairs(GMSetting:getSettings()) do
        if group.name == name then
            settings = group
        end
    end
    if not settings then
        return
    end
    local rowSize = self.gvItems:getRowSize()
    local data = {}
    local currentPos = 0
    local filter = self.etFilterValue:GetText()
    local function addItem(item)
        currentPos = currentPos + 1
        if filter == "" then
            table.insert(data, item)
        elseif string.find(item.name, filter) ~= nil then
            table.insert(data, item)
        end
    end
    for _, _item in pairs(settings.items) do
        if _item.func == "" then
            ---换行
            while currentPos < rowSize do
                addItem(_item)
            end
        else
            addItem(_item)
        end
        if currentPos == rowSize then
            currentPos = 0
        end
    end
    self.settings = settings
    self.adapter:setData(data)
    if self.settings.offset and self.settings.offset ~= 0 then
        local offset = self.settings.offset
        self.adapter:setScrollOffset(offset)
        self:addTimer(LuaTimer:scheduleTicker(function()
            self.adapter:setScrollOffset(offset)
        end, 1, 3))
    end
end

function UIGMControlPanel:isIgnoreLock()
    return true
end

function UIGMControlPanel:setBackgroundColor(color)
    self.root:SetBackgroundColor(color)
end

return UIGMControlPanel